import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { courses } from '../data/courses';
import paymentModal from '../components/paymentModal';
import Navbar from '../components/Navbar';

const Home = () => {
  const [selectedCourse, setSelectedCourse] = useState(null);
  const searchRef = useRef(null);

  useEffect(() => {
    const handleKey = (e) => { if (e.key === '/') searchRef.current?.focus(); };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, []);

  return (
    <div className="bg-[#020617] min-h-screen text-white font-sans selection:bg-blue-500/30">
      <Navbar />

      <section className="py-24 text-center px-4">
        <h1 className="text-6xl font-black mb-6 bg-gradient-to-b from-white to-slate-500 bg-clip-text text-transparent">
          CYBER-ACADEMY
        </h1>
        <p className="text-slate-400 max-w-lg mx-auto mb-6 text-sm">
          Déployez vos compétences d'élite. Infrastructure réelle, résultats concrets.
        </p>
        <input
          ref={searchRef}
          placeholder="Recherche (/)..."
          className="bg-slate-950 border border-slate-800 px-4 py-2 rounded-full text-xs w-64 mx-auto block focus:border-blue-500 outline-none transition-all"
        />
      </section>

      <div className="max-w-6xl mx-auto grid md:grid-cols-3 gap-6 px-8 pb-20">
        {courses.map(course => (
          <div key={course.id} className="group p-8 bg-slate-950 border border-slate-900 rounded-2xl hover:border-blue-500/50 transition-all shadow-xl hover:-translate-y-2">
            <span className={`text-[10px] font-mono px-3 py-1 rounded-full ${course.isFree ? 'bg-emerald-500/10 text-emerald-400' : 'bg-blue-500/10 text-blue-400'}`}>
              {course.isFree ? 'GRATUIT' : 'PREMIUM'}
            </span>
            <h3 className="text-lg font-bold mt-4 mb-2">{course.title}</h3>
            <p className="text-slate-500 text-xs mb-6 h-12">{course.description}</p>
            <div className="flex gap-3">
              <Link to={`/course/${course.id}`} className="flex-1 text-center border border-slate-700 py-3 rounded-lg text-xs font-bold uppercase hover:bg-slate-900 transition">
                Détails
              </Link>
              <button onClick={() => setSelectedCourse(course)} className="flex-1 bg-blue-600 py-3 rounded-lg text-xs font-bold uppercase hover:bg-blue-500 transition">
                {course.isFree ? 'Accéder' : 'Débloquer'}
              </button>
            </div>
          </div>
        ))}
      </div>

      {selectedCourse && <paymentModal course={selectedCourse} onClose={() => setSelectedCourse(null)} />}
    </div>
  );
};
export default Home;
